#!/bin/bash

# 🦀 Rust 환경 설정 자동화 스크립트
# 사용: ./scripts/setup-rust.sh

set -e

# 색상 정의
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
RED='\033[0;31m'
BLUE='\033[0;34m'
NC='\033[0m' # No Color

# 헬퍼 함수
log_info() {
    echo -e "${BLUE}ℹ${NC} $1"
}

log_success() {
    echo -e "${GREEN}✅ $1${NC}"
}

log_error() {
    echo -e "${RED}❌ $1${NC}"
}

log_warning() {
    echo -e "${YELLOW}⚠️  $1${NC}"
}

# 시스템 확인
check_system() {
    log_info "시스템 요구사항 확인 중..."

    if ! command -v curl &> /dev/null; then
        log_error "curl이 설치되지 않았습니다"
        exit 1
    fi

    log_success "curl 확인됨"
}

# rustup 설치
install_rustup() {
    log_info "rustup 설치 중..."

    if command -v rustup &> /dev/null; then
        log_success "rustup이 이미 설치됨"
        return
    fi

    # rustup 설치
    curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs | sh -s -- -y --no-modify-path

    # PATH에 추가
    export PATH="$HOME/.cargo/bin:$PATH"

    log_success "rustup 설치 완료"
}

# Rust 기본값 설정
configure_rust() {
    log_info "Rust 기본값 설정 중..."

    rustup default stable
    rustup update

    # 추가 컴포넌트
    rustup component add rustfmt clippy

    log_success "Rust 기본값 설정 완료"
}

# 버전 확인
verify_installation() {
    log_info "설치 검증 중..."

    local rustc_version=$(rustc --version)
    local cargo_version=$(cargo --version)

    echo "  $rustc_version"
    echo "  $cargo_version"

    log_success "설치 검증 완료"
}

# Rust 예제 디렉토리 생성
setup_examples() {
    log_info "예제 디렉토리 설정 중..."

    mkdir -p examples/rust

    # 예제 파일 생성
    cat > examples/rust/hello.rs << 'EOF'
fn main() {
    println!("Hello, World!");
}
EOF

    cat > examples/rust/ownership.rs << 'EOF'
fn main() {
    let s1 = String::from("Hello");
    let s2 = s1;  // ownership 이동

    let s3 = String::from("World");
    let len = calculate_length(&s3);

    println!("{} {}", s3, len);
}

fn calculate_length(s: &String) -> usize {
    s.len()
}
EOF

    cat > examples/rust/pattern_match.rs << 'EOF'
fn main() {
    let number = 5;

    match number {
        1 => println!("One"),
        2 | 3 | 5 | 7 | 11 => println!("Prime"),
        13..=19 => println!("Teens"),
        _ => println!("Other"),
    }
}
EOF

    cat > examples/rust/error_handling.rs << 'EOF'
fn main() {
    match divide(10, 2) {
        Ok(value) => println!("Result: {}", value),
        Err(e) => println!("Error: {}", e),
    }
}

fn divide(a: i32, b: i32) -> Result<i32, String> {
    if b == 0 {
        Err(String::from("Division by zero"))
    } else {
        Ok(a / b)
    }
}
EOF

    cat > examples/rust/traits.rs << 'EOF'
trait Drawable {
    fn draw(&self);
}

struct Circle {
    radius: f64,
}

impl Drawable for Circle {
    fn draw(&self) {
        println!("Drawing circle with radius {}", self.radius);
    }
}

fn main() {
    let circle = Circle { radius: 5.0 };
    circle.draw();
}
EOF

    log_success "예제 디렉토리 설정 완료"
}

# Rust 예제 테스트
test_examples() {
    log_info "Rust 예제 테스트 중..."

    local examples=(
        "examples/rust/hello.rs"
        "examples/rust/ownership.rs"
        "examples/rust/pattern_match.rs"
        "examples/rust/error_handling.rs"
        "examples/rust/traits.rs"
    )

    for example in "${examples[@]}"; do
        if [ -f "$example" ]; then
            log_info "테스트: $example"
            rustc "$example" -o "/tmp/rust_test" 2>&1 | head -5 || true
            log_success "컴파일 가능: $example"
        fi
    done

    log_success "예제 테스트 완료"
}

# 성능 벤치마크 준비
setup_benchmarks() {
    log_info "벤치마크 설정 중..."

    mkdir -p benchmarks/rust

    cat > benchmarks/rust/fibonacci.rs << 'EOF'
use std::time::Instant;

fn fibonacci(n: u32) -> u32 {
    match n {
        0 => 0,
        1 => 1,
        _ => fibonacci(n - 1) + fibonacci(n - 2),
    }
}

fn fibonacci_iter(n: u32) -> u32 {
    let mut a = 0;
    let mut b = 1;
    for _ in 0..n {
        let temp = a + b;
        a = b;
        b = temp;
    }
    a
}

fn main() {
    // 재귀 벤치마크
    let start = Instant::now();
    let result = fibonacci(10);
    let duration = start.elapsed();
    println!("Recursive Fibonacci(10) = {}, Time: {:?}", result, duration);

    // 반복 벤치마크
    let start = Instant::now();
    let result = fibonacci_iter(10);
    let duration = start.elapsed();
    println!("Iterative Fibonacci(10) = {}, Time: {:?}", result, duration);
}
EOF

    log_success "벤치마크 설정 완료"
}

# 메인 실행
main() {
    echo ""
    echo "╔════════════════════════════════════════╗"
    echo "║  🦀 Rust 환경 설정 자동화              ║"
    echo "╚════════════════════════════════════════╝"
    echo ""

    check_system
    install_rustup
    configure_rust
    verify_installation
    setup_examples
    test_examples
    setup_benchmarks

    echo ""
    echo "╔════════════════════════════════════════╗"
    echo "║  ✅ Rust 환경 설정 완료!              ║"
    echo "╚════════════════════════════════════════╝"
    echo ""
    echo "다음 단계:"
    echo "  1. 예제 컴파일: rustc examples/rust/hello.rs"
    echo "  2. 벤치마크: rustc -O benchmarks/rust/fibonacci.rs"
    echo "  3. 문서: RUST_INTEGRATION.md 참조"
    echo ""
}

main "$@"

