    let duration = start.elapsed();
    println!("  to_uppercase (10k): {:?}", duration);

    // Split
    let csv = "a,b,c,d,e,f,g,h,i,j";
    let start = Instant::now();
    for _ in 0..10000 {
        let _parts: Vec<&str> = csv.split(',').collect();
    }
    let duration = start.elapsed();
    println!("  String split (10k): {:?}", duration);

    // Replace
    let start = Instant::now();
    for _ in 0..1000 {
        let _replaced = s.replace("Rust", "Performance");
    }
    let duration = start.elapsed();
    println!("  String replace (1k): {:?}", duration);
}

// ============================================================
// 3️⃣ Array Operations - 배열 연산 성능
// ============================================================

fn array_operations() {
    let data: Vec<i32> = (1..=1000).collect();

    // Length
    let start = Instant::now();
    for _ in 0..100000 {
        let _len = data.len();
    }
    let duration = start.elapsed();
    println!("  Array length (100k): {:?}", duration);

    // Map
    let start = Instant::now();
    let _squared: Vec<i32> = data.iter().map(|x| x * x).collect();
    let duration = start.elapsed();
    println!("  Array map (1k elements): {:?}", duration);

    // Filter
    let start = Instant::now();
    let _evens: Vec<i32> = data.iter().filter(|x| *x % 2 == 0).copied().collect();
    let duration = start.elapsed();
    println!("  Array filter (1k elements): {:?}", duration);

    // Fold/Sum
    let start = Instant::now();
    let _sum: i32 = data.iter().sum();
    let duration = start.elapsed();
    println!("  Array sum (1k elements): {:?}", duration);

    // Fold with custom operation
    let start = Instant::now();
    let _product: i32 = data.iter().take(10).fold(1, |acc, x| acc * x);
    let duration = start.elapsed();
    println!("  Array fold (10 elements): {:?}", duration);

    // Reverse
    let start = Instant::now();
    let mut data_copy = data.clone();
    data_copy.reverse();
    let duration = start.elapsed();
    println!("  Array reverse (1k elements): {:?}", duration);

    // Sort
    let mut data_copy = (1..=1000).rev().collect::<Vec<i32>>();
    let start = Instant::now();
    data_copy.sort();
    let duration = start.elapsed();
    println!("  Array sort (1k elements): {:?}", duration);

    // Already sorted
    let start = Instant::now();
    data_copy.sort();
    let duration = start.elapsed();
    println!("  Array sort (already sorted): {:?}", duration);
}

// ============================================================
// 4️⃣ 메모리 효율성 - Iterator vs Allocated Vector
// ============================================================

fn memory_efficiency() {
    // 방법 1: Iterator (메모리 효율)
    let start = Instant::now();
    let _sum: i32 = (1..=100000).filter(|x| x % 2 == 0).sum();
    let duration1 = start.elapsed();

    // 방법 2: Vec 할당 (일반적)
    let start = Instant::now();
    let data: Vec<i32> = (1..=100000).filter(|x| x % 2 == 0).collect();
    let _sum: i32 = data.iter().sum();
    let duration2 = start.elapsed();

    println!("  Iterator (lazy): {:?}", duration1);
    println!("  Vec (allocated): {:?}", duration2);
    println!("  Difference: {:?}", duration2.as_nanos() as i128 - duration1.as_nanos() as i128);
}

// ============================================================
// 5️⃣ 패턴 매칭 - Match vs If-Else 성능
// ============================================================

fn pattern_matching_performance() {
    // 패턴 매칭 방식
    let start = Instant::now();
    for i in 0..100000 {
        match i % 10 {
            0 => { let _ = "Zero"; },
            1 => { let _ = "One"; },
            2..=5 => { let _ = "Two-Five"; },
            6..=9 => { let _ = "Six-Nine"; },
            _ => { let _ = "Other"; },
        }
    }
    let duration = start.elapsed();
    println!("  Pattern match (100k): {:?}", duration);

    // If-else 방식
    let start = Instant::now();
    for i in 0..100000 {
        let val = i % 10;
        if val == 0 {
            let _ = "Zero";
        } else if val == 1 {
            let _ = "One";
        } else if val >= 2 && val <= 5 {
            let _ = "Two-Five";
        } else if val >= 6 && val <= 9 {
            let _ = "Six-Nine";
        } else {
            let _ = "Other";
        }
    }
    let duration = start.elapsed();
    println!("  If-else (100k): {:?}", duration);
}

// ============================================================
// 6️⃣ Iterator Chaining - 복합 연산 성능
// ============================================================

fn iterator_chaining() {
    let data: Vec<i32> = (1..=10000).collect();

    // 단계별 연산
    let start = Instant::now();
    let result: i32 = data
        .iter()
        .filter(|x| x % 2 == 0)
        .map(|x| x * x)
        .take(100)
        .sum();
    let duration = start.elapsed();

    println!("  Iterator chain (10k → filter → map → take → sum): {:?}", duration);
    println!("    Result: {}", result);

    // Vec를 사용한 방식 (비교)
    let start = Instant::now();
    let filtered: Vec<i32> = data.iter().filter(|x| x % 2 == 0).copied().collect();
    let mapped: Vec<i32> = filtered.iter().map(|x| x * x).copied().collect();
    let result: i32 = mapped.iter().take(100).sum();
    let duration = start.elapsed();

    println!("  Vec-based (multiple allocations): {:?}", duration);
    println!("    Result: {}", result);
}

